package io.github.diodeme.ji.session.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class MemorySessionStoreTest {
    @Test
    void enforcesRevisionRunOwnershipAndImmutableSnapshots() {
        var store = new MemorySessionStore();
        var created = store.create("session-1", new ModelRef("faux", "model"), ".");
        var user = new Message("message-1", Message.Role.USER, List.of(new Content.Text("hello")), Instant.EPOCH);
        var running = store.startRun("session-1", "run-1", user, created.revision());
        assertThrows(IllegalStateException.class, () -> store.startRun("session-1", "run-2", user, running.revision()));
        assertThrows(IllegalStateException.class, () -> store.append("session-1", "run-2", List.of(), Usage.ZERO,
                Optional.empty(), running.revision()));
        assertThrows(IllegalStateException.class, () -> store.append("session-1", "run-1", List.of(), Usage.ZERO,
                Optional.empty(), created.revision()));
        var finished = store.append("session-1", "run-1", List.of(), Usage.ZERO, Optional.empty(), running.revision());
        assertEquals(2, finished.revision());
        assertEquals(List.of(user), store.load("session-1").orElseThrow().transcript());
    }
}
